import java.util.Scanner;

public class Main {
    static final int MAXN = 250005;
    static int totalN, maxK, modVal;
    static long[][] memoDP = new long[26][MAXN];
    static long[] fact = new long[MAXN];
    static long[] invFact = new long[MAXN];

    static long fastExponentiation(long base, long exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) result = result * base % modVal;
            base = base * base % modVal;
            exponent >>= 1;
        }
        return result;
    }

    static int lowbit(int x) {
        return x & -x;
    }

    static long compute(int level, int mask) {
        if (memoDP[level][mask] != -1) return memoDP[level][mask];
        if (mask == 0) {
            long res = fact[totalN];
            for (int i = 1; i <= level; i++)
                res = res * (maxK - i + 1) % modVal;
            memoDP[level][mask] = res;
            return res;
        }
        long res = 0;
        int tmp_mask = mask - lowbit(mask);
        for (int sub_mask = tmp_mask; sub_mask > 0; sub_mask = (sub_mask - 1) & tmp_mask)
            res = (res + invFact[mask - sub_mask] * compute(level + 1, sub_mask)) % modVal;
        res = (res + invFact[mask] * compute(level + 1, 0)) % modVal;
        memoDP[level][mask] = res;
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        totalN = sc.nextInt();
        maxK = sc.nextInt();
        modVal = sc.nextInt();

        long answer = fastExponentiation(maxK, totalN);
        if ((totalN & 1) == 1) {
            System.out.println(answer);
            sc.close();
            return;
        }

        for (int i = 0; i <= totalN; i++) {
            fact[i] = 1;
        }
        for (int i = 1; i <= totalN; i++) {
            fact[i] = fact[i - 1] * i % modVal;
        }
        invFact[totalN] = fastExponentiation(fact[totalN], modVal - 2);
        for (int i = totalN; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % modVal;
        }

        for (int i = 0; i <= 25; i++) {
            for (int j = 0; j <= totalN; j++) {
                memoDP[i][j] = -1;
            }
        }

        answer = (answer - compute(0, totalN) + modVal) % modVal;
        System.out.println(answer);
        sc.close();
    }
}
